fn element_wise_divide(arr1: &Vec<u32>, arr2: &Vec<u32>) -> Vec<u32> {
    assert!(
        arr1.len() == arr2.len(),
        "Input arrays must have the same length"
    );

    let mut result: Vec<u32> = Vec::with_capacity(arr1.len());

    for i in 0..arr1.len() {
        let denom = arr2[i];
        assert!(denom != 0, "Division by zero at index {}", i);

        let q = arr1[i] / denom;

        // Per problem statement, quotient fits in i32 range; we defensively assert it.
        assert!(
            q <= i32::MAX as u32,
            "Quotient out of i32 range at index {}",
            i
        );

        result.push(q);
    }

    result
}